import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.DSoq407f.js";const p=JSON.parse('{"title":"插件市场审核","description":"","frontmatter":{},"headers":[],"relativePath":"admin/marketplace.md","filePath":"admin/marketplace.md","lastUpdated":1782304957000}'),l={name:"admin/marketplace.md"};function i(n,t,s,d,c,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="插件市场审核" tabindex="-1">插件市场审核 <a class="header-anchor" href="#插件市场审核" aria-label="Permalink to &quot;插件市场审核&quot;">​</a></h1><blockquote><p>审核开发者上传的插件，把控市场质量与安全。</p></blockquote><h2 id="审核流程" tabindex="-1">审核流程 <a class="header-anchor" href="#审核流程" aria-label="Permalink to &quot;审核流程&quot;">​</a></h2><p>开发者上传插件后（默认不上架，见<a href="./../plugin-dev/publish">发布与上架</a>），需要平台审核才能正式进入市场：</p><ol><li><strong>待审核</strong>：开发者提交上架申请。</li><li><strong>审核中</strong>：管理员查看插件。</li><li><strong>通过</strong>：插件在市场上架，可被购买。</li><li><strong>拒绝</strong>：附原因退回，开发者修改后重新提交。</li></ol><h2 id="审核要点" tabindex="-1">审核要点 <a class="header-anchor" href="#审核要点" aria-label="Permalink to &quot;审核要点&quot;">​</a></h2><p>审核一个插件时关注：</p><ul><li><strong>功能正常</strong>：核心功能能否跑通，有没有明显 bug。</li><li><strong>安全合规</strong>：没有恶意行为（偷数据、挖矿、后门），不违规。</li><li><strong>代码质量</strong>：异常处理是否到位，会不会拖垮运行时。</li><li><strong>描述准确</strong>：<code>meta.yaml</code> 的描述与实际功能一致。</li><li><strong>配置合理</strong>：<code>setting.json</code> 字段有默认值、说明清楚。</li></ul><div class="tip custom-block"><p class="custom-block-title">可以装到测试机器人验证</p><p>审核时把插件装到一个测试机器人上，实际发消息验证功能，比光看代码更可靠。</p></div><h2 id="插件管理" tabindex="-1">插件管理 <a class="header-anchor" href="#插件管理" aria-label="Permalink to &quot;插件管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>下架</strong></td><td>已上架插件发现问题，临时下架</td></tr><tr><td><strong>强制停用</strong></td><td>紧急停用某个有问题的插件</td></tr><tr><td><strong>分类调整</strong></td><td>调整插件分类</td></tr><tr><td><strong>删除</strong></td><td>彻底移除（慎用，影响已购买用户）</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>管理插件作者 → <a href="./developers">开发者管理</a></li><li>插件开发规范 → <a href="./../plugin-dev/getting-started">插件开发</a></li></ul>',13)])])}const u=a(l,[["render",i]]);export{p as __pageData,u as default};
